def make_city_code(rumba_city_region):
    raw = (rumba_city_region or "").upper()

    # Ambil huruf A-Z saja
    letters = ""
    for ch in raw:
        if "A" <= ch <= "Z":
            letters += ch

    if not letters:
        frappe.throw("Kota cabang (rumba_city_region) wajib diisi.")

    # Prioritas konsonan: Pangkalpinang -> PKP
    consonants = ""
    vowels = ""
    for ch in letters:
        if ch in "AEIOU":
            vowels += ch
        else:
            consonants += ch

    return (consonants + vowels + "XXX")[:3]


# Generate otomatis hanya jika belum diisi manual
if not doc.rumba_branch_code:
    city_code = make_city_code(doc.rumba_city_region)

    rows = frappe.get_all(
        "Branch",
        filters={"rumba_branch_code": ["like", city_code + "%"]},
        fields=["rumba_branch_code"],
        order_by="rumba_branch_code desc",
        limit=500
    )

    max_no = 0
    for row in rows:
        code = row.get("rumba_branch_code") or ""
        if len(code) == 5 and code[:3] == city_code and code[3:].isdigit():
            n = int(code[3:])
            if n > max_no:
                max_no = n

    next_no = max_no + 1
    if next_no > 99:
        frappe.throw("Kode cabang untuk prefix " + city_code + " sudah mencapai batas 99.")

    doc.rumba_branch_code = city_code + str(next_no).zfill(2)
